import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.Ch4PdLd_.js";const c=JSON.parse('{"title":"在隔离环境中运行","description":"","frontmatter":{},"headers":[],"relativePath":"guide/containerization.md","filePath":"guide/containerization.md"}'),t={name:"guide/containerization.md"};function l(p,s,h,k,d,o){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="在隔离环境中运行" tabindex="-1">在隔离环境中运行 <a class="header-anchor" href="#在隔离环境中运行" aria-label="Permalink to &quot;在隔离环境中运行&quot;">​</a></h1><p>隔离环境用来限制模型生成的命令能访问或影响的文件、凭据、进程和网络服务。可以把整个 nek 进程放进隔离环境，也可以让 nek 留在宿主机、只把内置工具路由到隔离环境里执行。</p><h2 id="选择隔离方式" tabindex="-1">选择隔离方式 <a class="header-anchor" href="#选择隔离方式" aria-label="Permalink to &quot;选择隔离方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>nek 运行在</th><th>被隔离的部分</th><th>凭据</th><th>适合</th></tr></thead><tbody><tr><td>Docker</td><td>容器内</td><td>nek、内置工具、<code>!</code> 命令、扩展</td><td>传进容器的凭据在容器内可见</td><td>简单直接的本地容器边界</td></tr><tr><td>Gondolin 扩展</td><td>宿主机</td><td>内置工具和 <code>!</code> 命令</td><td>存储的凭据留在宿主机，但命令会继承宿主机的环境变量</td><td>用本地微型虚拟机执行工具，同时保留宿主机上的界面</td></tr></tbody></table><p>隔离方式决定了扩展在哪里运行：整个 nek 在隔离环境里时，扩展也在里面；用 Gondolin 只路由内置工具时，其他扩展的工具仍在宿主机上运行，除非它们也把工作委托给隔离环境。</p><div class="info custom-block"><p class="custom-block-title">Docker Sandboxes 和 OpenShell</p><p><a href="https://docs.docker.com/ai/sandboxes/" target="_blank" rel="noreferrer">Docker Sandboxes</a> 和 <a href="https://docs.nvidia.com/openshell/about/overview" target="_blank" rel="noreferrer">NVIDIA OpenShell</a> 目前公开的镜像（<code>pi-kit</code>、<code>pi</code>）安装的是上游 pi，不是 nek，还没有 nek 的 kit。要隔离 nek 本身，请使用下面的 Docker 方案，或在这些平台的通用沙箱里按 Docker 方案中的步骤安装 nek。</p></div><h2 id="先想清楚-nek-能访问什么" tabindex="-1">先想清楚 nek 能访问什么 <a class="header-anchor" href="#先想清楚-nek-能访问什么" aria-label="Permalink to &quot;先想清楚 nek 能访问什么&quot;">​</a></h2><p>隔离环境里的进程仍然能影响你暴露给它的资源：</p><ul><li>以读写方式挂载的宿主机目录，nek 可以修改；</li><li>挂载 <code>~/.nek/agent</code> 会暴露你的 nek 凭据、设置、扩展和会话；</li><li>传进容器的环境变量，容器内的所有进程都能读到；</li><li>有网络访问时，代码或工具输出可能被发送出去；</li><li>只隔离工具的方案，限制不了宿主机上的 nek 进程和不走隔离后端的扩展工具。</li></ul><p>只暴露任务需要的工作目录、凭据和网络目的地。不希望写入影响宿主机时，用只读挂载，或者把文件复制进去、做完再复制出来。</p><h2 id="docker" tabindex="-1">在 Docker 中运行 nek <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;在 Docker 中运行 nek {#docker}&quot;">​</a></h2><h3 id="构建镜像" tabindex="-1">构建镜像 <a class="header-anchor" href="#构建镜像" aria-label="Permalink to &quot;构建镜像&quot;">​</a></h3><p>创建 <code>Dockerfile.nek</code>：</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node:24-bookworm-slim</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apt-get update \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &amp;&amp; apt-get install -y --no-install-recommends bash ca-certificates curl git unzip ripgrep fd-find \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &amp;&amp; ln -s /usr/bin/fdfind /usr/local/bin/fd \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &amp;&amp; rm -rf /var/lib/apt/lists/*</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装 nek：源码放在 /opt/nekcode，nek 命令放在 /usr/local/bin</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> curl -fsSL https://raw.githubusercontent.com/deepdarkpaw/nekcode/nek/scripts/install.sh \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  | NEK_INSTALL_DIR=/opt/nekcode NEK_BIN_DIR=/usr/local/bin bash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /workspace</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTRYPOINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nek&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>在 <code>Dockerfile.nek</code> 所在目录构建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nek-sandbox</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Dockerfile.nek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><h3 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h3><p>在你希望 nek 访问的工作目录里运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:/workspace&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nek-agent-home:/root/.nek/agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  nek-sandbox</span></span></code></pre></div><ul><li>把 <code>ANTHROPIC_API_KEY</code> 换成你的服务商需要的变量；</li><li>名为 <code>nek-agent-home</code> 的卷保存容器内的设置、凭据和会话，下次运行还在；</li><li>除非你希望容器访问宿主机的 nek 配置和凭据，否则<strong>不要</strong>挂载宿主机的 <code>~/.nek/agent</code>。</li></ul><p>非交互地运行一次任务：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:/workspace&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nek-sandbox</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;列出失败的测试并分析原因&quot;</span></span></code></pre></div><h3 id="验证工作目录" tabindex="-1">验证工作目录 <a class="header-anchor" href="#验证工作目录" aria-label="Permalink to &quot;验证工作目录&quot;">​</a></h3><p>在 nek 里运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!pwd</span></span></code></pre></div><p>应该输出 <code>/workspace</code>。<code>/workspace</code> 下的改动会直接写到宿主机挂载的目录。不能接受时去掉挂载或改用只读挂载（<code>-v &quot;$PWD:/workspace:ro&quot;</code>）。</p><h2 id="gondolin" tabindex="-1">用 Gondolin 隔离工具 <a class="header-anchor" href="#gondolin" aria-label="Permalink to &quot;用 Gondolin 隔离工具 {#gondolin}&quot;">​</a></h2><p><a href="https://github.com/earendil-works/gondolin" target="_blank" rel="noreferrer">Gondolin</a> 是一个本地 Linux 微型虚拟机。仓库里的示例扩展让 nek 进程和基于文件的服务商凭据留在宿主机，把内置工具和你输入的 <code>!</code> 命令路由到虚拟机里执行。</p><div class="warning custom-block"><p class="custom-block-title">环境变量会进入虚拟机</p><p>虚拟机里的命令继承宿主机进程的环境变量，所以通过环境变量提供的服务商 key 在虚拟机里可见。除非你移除敏感变量或修改扩展的环境处理方式，否则不要把这种方案当作凭据边界。</p></div><p>Gondolin 需要 Node.js 23.6 或更高版本，以及通过系统包管理器安装的 QEMU。</p><h3 id="安装扩展" tabindex="-1">安装扩展 <a class="header-anchor" href="#安装扩展" aria-label="Permalink to &quot;安装扩展&quot;">​</a></h3><p>在 nek 的源码目录里（安装脚本默认放在 <code>~/.local/share/nekcode</code>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/nekcode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nek/agent/extensions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/coding-agent/examples/extensions/gondolin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nek/agent/extensions/gondolin</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nek/agent/extensions/gondolin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-scripts</span></span></code></pre></div><p>放在 <code>~/.nek/agent/extensions/</code> 下的扩展会被自动加载。</p><h3 id="启动-1" tabindex="-1">启动 <a class="header-anchor" href="#启动-1" aria-label="Permalink to &quot;启动&quot;">​</a></h3><p>在要挂载的工作目录里启动 nek：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/working-folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span></span></code></pre></div><p>扩展把宿主机的工作目录挂载到虚拟机的 <code>/workspace</code>，并替换 <code>read</code>、<code>write</code>、<code>edit</code>、<code>bash</code>、<code>grep</code>、<code>find</code>、<code>ls</code>。<code>/workspace</code> 下的改动直接写到宿主机。</p><p>其他扩展的工具仍在宿主机上运行，除非它们显式委托执行。添加可能绕过虚拟机边界的工具前，先阅读示例扩展的源码。</p><p>不想每次都加载它时，把扩展放在别处，用 <code>nek -e &lt;路径&gt;</code> 按需加载，见 <a href="/nekcode/customize/loading-extensions">加载扩展</a>。</p>`,40)])])}const g=i(t,[["render",l]]);export{c as __pageData,g as default};
